/* ============================================================
   ITEM CATALOG BUILDER
   ============================================================ */
function _slug(s) {
    return String(s).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
}

function buildCatalog(rows) {
    const catalog = {};
    rows.forEach(([category, item, brand]) => {
        let normCategory = String(category || "").trim();
        if (/screen\s*[→\->]\s*module/i.test(normCategory)) {
            normCategory = "Screen → Module";
        }
        if (!catalog[normCategory]) catalog[normCategory] = {};
        if (!catalog[normCategory][item]) catalog[normCategory][item] = [];
        /* Point spec sheet links to the new local specs.html page */
        const specUrl = `../pages/specs.html?category=${encodeURIComponent(normCategory)}&item=${encodeURIComponent(item)}`;
        catalog[normCategory][item].push({
            brand,
            spec: item,
            link: specUrl
        });
    });
    return catalog;
}

/* ============================================================
   ITEM CATALOG — Full catalog of products and services
   ============================================================ */
let ITEM_CATALOG = {};
try {
    ITEM_CATALOG = JSON.parse(localStorage.getItem("kan_products")) || {};
} catch (e) {
    console.error("Failed to parse cached products:", e);
}

async function loadDynamicProducts() {
    try {
        const res = await fetch(`${GOOGLE_SHEET_WEBAPP_URL}?action=getProducts&bypassCache=true&t=${Date.now()}`);
        const json = await res.json();
        if (json.status === "success" && json.data) {
            const rows = json.data;
            const newCatalog = {};
            rows.forEach(row => {
                let category = String(row[0] || "").trim();
                const item = String(row[1] || "").trim();
                const brand = String(row[2] || "").trim();
                const spec = String(row[3] || "").trim();
                if (!category) return;

                if (/screen\s*[→\->]\s*module/i.test(category)) {
                    category = "Screen → Module";
                }

                if (!newCatalog[category]) newCatalog[category] = {};
                if (!newCatalog[category][item]) newCatalog[category][item] = [];

                const specUrl = `../pages/specs.html?category=${encodeURIComponent(category)}&item=${encodeURIComponent(item)}`;
                newCatalog[category][item].push({
                    brand,
                    spec: spec || item,
                    link: specUrl
                });
            });
            ITEM_CATALOG = newCatalog;
            localStorage.setItem("kan_products", JSON.stringify(newCatalog));
            // trigger re-render of dropdowns if already rendered
            if (typeof renderLineItems === 'function') {
                renderLineItems();
            }
        }
    } catch (e) {
        console.error("Failed to load products dynamically:", e);
    }
}

/* ============================================================
   AUTH HELPERS
   ============================================================ */

/** Authenticate user — returns employee object or null */
function authenticateUser(id, password) {
    if (!id || !password) return null;
    return EMPLOYEES.find(
        e => e.id.toUpperCase() === id.trim().toUpperCase() &&
            e.password === password.trim()
    ) || null;
}

/** Get current session user from sessionStorage */
function getSessionUser() {
    try {
        const raw = sessionStorage.getItem("kan_session");
        return raw ? JSON.parse(raw) : null;
    } catch {
        return null;
    }
}

/** Save session */
function setSessionUser(emp) {
    sessionStorage.setItem("kan_session", JSON.stringify(emp));
}

/** Clear session */
function clearSession() {
    sessionStorage.removeItem("kan_session");
    sessionStorage.removeItem("kan_active_quote");
}

/** Guard — redirect to login if not authenticated */
function requireAuth() {
    if (!getSessionUser()) {
        window.location.href = "../index.html";
        return false;
    }
    return true;
}
